sql.where:
tm.deleted = 0



    AND tm.maintenance_id = #{reqVO.maintenanceId}


    AND tm.transfer_id = #{reqVO.transferId}


    AND tm.equipment_id = #{reqVO.equipmentId}




    AND tm.maintenance_cycle LIKE CONCAT('%', #{reqVO.maintenanceCycle}, '%')




    AND tm.last_maintenance_time BETWEEN #{reqVO.lastMaintenanceTime[0]} AND #{reqVO.lastMaintenanceTime[1]}




    AND tm.maintenance_content LIKE CONCAT('%', #{reqVO.maintenanceContent}, '%')




    AND tm.handle_by = #{reqVO.handleBy}




    AND tm.maintenance_status = #{reqVO.maintenanceStatus}




    AND tm.expected_complete_time BETWEEN #{reqVO.expectedCompleteTime[0]} AND #{reqVO.expectedCompleteTime[1]}




    AND tm.abnormal_is_timeout = #{reqVO.abnormalIsTimeout}




    AND tm.maintenance_time BETWEEN #{reqVO.maintenanceTime[0]} AND #{reqVO.maintenanceTime[1]}




    AND tm.replace_parts LIKE CONCAT('%', #{reqVO.replaceParts}, '%')




    AND tm.maintenance_cost = #{reqVO.maintenanceCost}




    AND tm.maintenance_photo LIKE CONCAT('%', #{reqVO.maintenancePhoto}, '%')




    AND tm.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
